        description="Record a SIP from the client's signed registration: a fixed amount into one mutual fund in one account, monthly on a day from 1 to 28, from a start date to an optional end. Only a plan the account's licence buys is accepted (direct for an adviser or a portfolio manager). On a demonstration firm the registration may be simulated, and is marked so. Each instalment is then bought at that day's NAV if the cash is there. A step-up is recorded only when the signed registration states it: its percentage, how often (every 12 or 6 months) and any cap; each later instalment then rises as registered. Never add or suggest a step-up the person did not say is on the registration. goal_id records which goal it saves towards.",
