        confirmation=None,
        inputs=[],
        output=ToolOutput("object", "The day's four figures and what is behind each"),
        roles_required={UserRole.ADVISER, UserRole.PARAPLANNER, UserRole.PORTFOLIO_TEAM, UserRole.BRANCH_LEADER},
