        description="Records a change to a screening list of an Indian firm from its notification: list_key unsc (UNSC sanctions), uapa (domestic list notified under UAPA) or pep (politically exposed persons), the change's own version, the day it changed, entries added each as 'name | father's name | date of birth YYYY-MM-DD | note' (last three optional) and names removed. No list feed is connected, so only what the person gives is recorded; never add a name they did not give. Recording it rescreens every party of record in the same step; each match is a signal a person decides with record_screening_decision. Compliance or operations.",
