        speaking_agent="astra",
        description="India: how the firm is licensed and governed, from what compliance recorded. section map is the licence map: which of the six licences the firm holds, what each track lets an agent do (may it place an order, does the client consent to each trade, which fund plans), how many mandates and filings sit under each, and which agents the licences cap, the configured tier beside the effective one. section policies is the governance register: grievance, cybersecurity, business continuity, outsourcing and conflict of interest policies, each with its version, owner, approval and next review (a year after approval unless the document sets another day), overdue shown, earlier versions kept. section counsel lists each Indian law figure with whether counsel has read it against its source (not reviewed by default, confirmed, corrected, not confirmed, or changed since the review). Leave section out for all three. A kind with no record does not mean the firm has no such policy, and none of this says the firm is compliant. To show it beside the conversation call open_view with view licences.",
