        speaking_agent="astra",
        description="India: records what goes into a person's EPF, PPF or NPS each month and who pays it, from a statement, passbook or payslip: scheme epf, ppf or nps; payer own or employer (PPF is own only; an employer's NPS contribution is payer employer, and for EPF record what the passbook credits to the provident fund, not the pension part). The retirement projection counts it, level, until retirement. A later statement replaces the earlier figure for the same scheme and payer; to say one stopped use end_retirement_record. Never estimate it or work it out from a salary. It moves no money.",
        change_state=ToolChangeState.PAUSE_FOR_CONFIRMATION,
        confirmation="Record this contribution? The retirement projection will count it.",
        inputs=[
            ToolInput("person_id", "uuid", "The member, from read_retirement_stack or read_household", required=True),
            ToolInput("scheme", "string", "epf, ppf or nps", required=True),
            ToolInput("payer", "string", "own or employer", required=True),
            ToolInput("monthly_amount", "number", "The amount a month, as the statement shows", required=True),
            ToolInput("statement_date", "string", "The statement's date, YYYY-MM-DD", required=True),
            ToolInput("document", "string", "The statement, passbook or payslip, and where it is filed", required=True),
        ],
        output=ToolOutput("object", "The household's retirement stack"),
        roles_required={UserRole.ADVISER, UserRole.PARAPLANNER, UserRole.OPERATIONS},
