        name="Record Annuity Rate",
        speaking_agent="astra",
        description="India: records the annuity rate an insurer quoted for a person's NPS exit, from the quote: the yearly income as a percentage of the amount paid for it, with its terms (single or joint life, return of purchase price) as quoted. The projection then reads the annuity part of their NPS at this rate; without one that part is not assessed. Never supply a typical or market rate. It buys nothing.",
        change_state=ToolChangeState.PAUSE_FOR_CONFIRMATION,
