        name="Record Unified Pension Scheme Membership",
        speaking_agent="astra",
        description="India: records that a person (central government staff) is in the Unified Pension Scheme, from a document. Only the membership is recorded: its assured pension is not worked out, and the person's NPS account and contributions leave the retirement projection because NPS exit rules do not apply to them.",
        change_state=ToolChangeState.PAUSE_FOR_CONFIRMATION,
