        description="Say how much of this household's plan a trigger asks for: full_rebuild or review_and_refresh, with the reason, from what the user knows of the household. It is added to the file and never edited; the latest stands. It is never worked out from the household's size, so use only what the user says. It changes no plan and no task.",
