        speaking_agent="astra",
        description="Record a filed US return's facts from the document (Form 1040 and its schedules), as the person reads them: tax_year, filing_status (single, married_filing_jointly, married_filing_separately, head_of_household, qualifying_surviving_spouse), person_ids (both spouses on a joint return, else one), agi, taxable_income, and where the person gives them marginal_rate, effective_rate, qbi_deduction, carryforwards ([{kind: capital_loss|charitable|net_operating_loss|investment_interest|other, amount}]), basis_8606 ([{person_id, amount}]) and state (two letters). source_document names the return. Never fill in a figure the person did not read off the return. It is added and never edited; an amended return is recorded again. The Roth room, the harvesting findings and the carryforwards then read it and name its year.",
